fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo, open Data Explorer, then the Dashboards section. Create a throwaway dashboard via the 'New' button so you have one you own, return to the list, then hover/locate its card (or list row) and click its Delete (trash) action button. A confirmation dialog titled 'Delete Dashboard' should appear warning the action cannot be undone. Confirm the deletion and verify the dashboard is removed from the list. Success is the confirmation dialog appearing AND the item disappearing after you confirm. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
